+  });
+});
+
+describe('provider stream-error objects (#335 item 2)', () => {
+  test('OpenAI server_error with a string code is a retryable APIError', () => {
+    const error = MessageV2.fromError(
+      {
+        message: 'The server had an error',
+        type: 'server_error',
+        code: 'server_error',
+        statusCode: 500,
+        isRetryable: true,
+      },
+      { providerID: 'openai' }
